// Route contract for this endpoint (read by wf.gateway.auth).
const route = {"method": "POST", "template": "/v1/legal/ask", "require_user": true, "idempotent": true, "required_consents": ["terms", "privacy"], "roles": []};
const item = $input.first();
return [{ json: { ...item.json, t0: Date.now(), route }, binary: item.binary }];

// wf.orchestrator > "Validate body"
// POST /v1/assistant/message {text (required, up to 2000 characters), jurisdiction (default: the
// account's)}. Media ids come with phase 4.
const gw = $input.first().json;
const b = gw.ctx.body || {};
const user = gw.ctx.user || {};
const details = [];
for (const k of Object.keys(b)) if (!['text', 'jurisdiction'].includes(k)) details.push({ field: k, issue: 'unknown_field' });
const text = typeof b.text === 'string' ? b.text.trim() : '';
if (!text) details.push({ field: 'text', issue: 'required' });
else if (Array.from(text).length > 2000) details.push({ field: 'text', issue: 'too_long', max: 2000 });
const jurisdiction = b.jurisdiction === undefined ? (user.jurisdiction_code || null) : b.jurisdiction;
if (jurisdiction !== null && (typeof jurisdiction !== 'string' || !/^[A-Z]{2}(-[A-Z0-9]{1,3})?$/.test(jurisdiction))) details.push({ field: 'jurisdiction', issue: 'invalid_format' });
if (details.length) {
  return [{ json: { ok: false, status: 422, gw, error: { code: 'VALIDATION_FAILED', message: 'Request body is invalid', details } } }];
}
return [{ json: { ok: true, gw, text, jurisdiction, today: new Date().toISOString().slice(0, 10) } }];

// wf.api.legal_ask > "Legal request" (platform P9, PLATFORM_SPEC 3.8): POST /v1/legal/ask goes straight to the Legal
// agent (A5), without the P1 router. Same input as the assistant path: the masked text (Text service, or the fallback
// mask), the language the Text service found, the jurisdiction asked or the account's.
// A3 Match agent checks (D-084), shared by the agent workflow and the unit tests.
//  - toolCalls(steps): the AI Agent node's intermediate steps as [{tool, input, output}] (output parsed when JSON).
//  - numbersIn(text): every reading of every number written in a text (see readings).
//  - checkAnswer(answer, sources): every number of two digits or more in the answer must appear in one of the
//    sources (the user's message, the tool results). Small numbers (result positions, counts up to 10) pass.
//  - fallbackMask(text): e-mails and long digit runs masked, used only when the Text service did not answer.
//  - plainText(answer): Markdown removed (bold, italics, headings, list markers, links), lines joined (D-085).
//  - shorten(text, max): cut at the last sentence end that fits, else at a word, with an ellipsis (D-085).

function toolCalls(steps) {
  return (Array.isArray(steps) ? steps : []).map((s) => {
    const a = s.action || {};
    let out = s.observation;
    if (typeof out === 'string') { try { out = JSON.parse(out); } catch (e) { /* keep the text */ } }
    if (Array.isArray(out) && out.length === 1) out = out[0];          // a workflow tool answers with its items
    let input = a.toolInput;
    if (typeof input === 'string') { try { input = JSON.parse(input); } catch (e) { /* keep the text */ } }
    return { tool: a.tool || null, input: input ?? null, output: out ?? null };
  });
}

// Each number written in a text, with its possible readings: "450.000" is 450 (Tunisian dinars, three decimals) or
// 450000 (dot as thousands separator); "1.225.000" is 1225000; "450,5" is 450.5.
function readings(text) {
  const out = [];
  for (const m of String(text || '').matchAll(/\d{1,3}(?:\.\d{3})+(?!\d|,\d)|\d+(?:[.,]\d+)?/g)) {
    const raw = m[0];
    const alts = new Set();
    if (/^\d{1,3}(?:\.\d{3})+$/.test(raw)) alts.add(Number(raw.replace(/\./g, '')));
    const v = Number(raw.replace(',', '.'));
    if (Number.isFinite(v)) alts.add(v);
    out.push([...alts]);
  }
  return out;
}

function numbersIn(text) {
  return readings(text).flat();
}

function checkAnswer(answer, sources) {
  const allowed = new Set();
  for (const src of sources || []) {
    const text = typeof src === 'string' ? src : JSON.stringify(src ?? '');
    for (const n of numbersIn(text)) {
      allowed.add(n);
      allowed.add(Math.round(n));
    }
  }
  const unsupported = [];
  for (const alts of readings(answer)) {
    if (alts.some((n) => Number.isInteger(n) && n <= 10)) continue;
    if (alts.some((n) => allowed.has(n) || allowed.has(Math.round(n)))) continue;
    unsupported.push(alts[alts.length - 1]);
  }
  return { ok: unsupported.length === 0, unsupported };
}

function fallbackMask(text) {
  return String(text || '')
    .replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '<EMAIL>')
    // a date written 2026-12-01 is not a phone number (F-079)
    .replace(/\+?\d[\d .-]{6,}\d/g, (m) => (/^\d{4}-\d{2}-\d{2}$/.test(m) || m.replace(/\D/g, '').length < 8 ? m : '<PHONE>'));
}

function plainText(answer) {
  const lines = String(answer || '').replace(/\r/g, '').split('\n').map((l) => l
    .replace(/^\s{0,3}#{1,6}\s+/, '')                      // headings
    .replace(/^\s*(?:[-*+\u2022]|\d+[.)])\s+/, '')            // list markers ("1." too: positions are said in words)
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')                // links: keep the text
    .replace(/(\*\*|__)(.+?)\1/g, '$2')                       // bold
    .replace(/(^|[^\w*])[*_]([^*_\n]+)[*_](?=[^\w*]|$)/g, '$1$2') // italics
    .replace(/`([^`]*)`/g, '$1')
    .replace(/[*_]{2,}/g, '')
    .trim()).filter(Boolean);
  return lines.join(' ').replace(/\s{2,}/g, ' ').trim();
}

function shorten(text, max) {
  const t = String(text || '');
  if (!max || Array.from(t).length <= max) return { text: t, cut: false };
  const head = Array.from(t).slice(0, max).join('');
  const ends = [...head.matchAll(/[.!?\u061F\u06D4](?=\s|$)/g)].map((m) => m.index + 1);
  if (ends.length && ends[ends.length - 1] >= max * 0.4) return { text: head.slice(0, ends[ends.length - 1]).trim(), cut: true };
  const sp = head.lastIndexOf(' ');
  return { text: (sp > max * 0.4 ? head.slice(0, sp) : head).trim() + '\u2026', cut: true };
}

if (typeof module !== 'undefined') module.exports = { toolCalls, readings, numbersIn, checkAnswer, fallbackMask, plainText, shorten };

const v = $('Validate body').first().json;
const tr = $('Text analysis').first().json || {};
const tb = tr.body && typeof tr.body === 'object' ? tr.body : null;
const masked = tb && tb.pii && typeof tb.pii.masked_text === 'string' ? tb.pii.masked_text : fallbackMask(v.text);
const lang = tb && tb.language ? tb.language : {};
return [{ json: { text: masked, language: lang.language || null, script: lang.script || null, jurisdiction: v.jurisdiction,
  today: v.today, user_id: v.gw.ctx.user_id, request_id: v.gw.request_id || v.gw.ctx.request_id } }];

// wf.api.legal_ask > "Legal answer": the Legal agent's checked answer, the same fields and checks as the assistant's
// legal_question answer (D-087), without the router's fields.
const v = $('Validate body').first().json;
const r = $('Legal request').first().json;
const a = $input.first().json || {};
const steps = Array.isArray(a.steps) ? a.steps : [];
if (a.ok !== true) {
  return [{ json: { ok: false, gw: v.gw, status: 503, steps, error: { code: 'UPSTREAM_UNAVAILABLE',
    message: 'The legal assistant is unavailable', details: [{ issue: a.error_code || 'agent_failed' }] } } }];
}
return [{ json: { ok: true, gw: v.gw, status: 200, steps, data: { language: r.language, jurisdiction: v.jurisdiction, status: a.status,
  answer: a.answer, abstained: a.abstained, abstain_reason: a.abstain_reason, conflict: a.conflict, citations: a.citations,
  missing_information: a.missing_information, notice_version: a.notice_version, warnings: a.warnings || [] } } }];

// wf.api.legal_ask > "Agent off": legal.agent_enabled is false; there is no fixed path behind the Legal agent.
const v = $('Validate body').first().json;
return [{ json: { ok: false, gw: v.gw, status: 503, error: { code: 'UPSTREAM_UNAVAILABLE', message: 'The legal assistant is off',
  details: [{ issue: 'agent_off' }] } } }];

// Shared by every API workflow > "Envelope"
// Input: either a handler result {ok:true, status, data, gw} or a rejection
// from the gateway or a handler {ok:false, status, error | replay+response}.
// Output: {status, response, finish} where finish is the app.api_finish payload.
const x = $input.first().json;
const gw = x.gw || x;                       // handlers carry the gateway item in x.gw
const t0 = gw.t0 || Date.now();
const latency = Date.now() - t0;
const requestId = gw.request_id || (gw.ctx && gw.ctx.request_id) || null;
let status, response;
if (x.replay) {
  status = x.status;
  response = x.response;                    // stored response, returned unchanged
} else if (x.ok) {
  status = x.status || 200;
  response = { request_id: requestId, data: x.data ?? {}, meta: { latency_ms: latency, ...(x.meta || {}) } };
} else {
  status = x.status || 500;
  const e = x.error || { code: 'INTERNAL', message: 'Internal error', details: [] };
  response = { request_id: requestId, error: { code: e.code, message: e.message, details: e.details || [] } };
}
const finish = {
  request_id: requestId,
  workflow: $workflow.name,
  n8n_execution_id: String($execution.id),
  user_id: (gw.ctx && gw.ctx.user_id) || '',
  channel: 'api',
  status_code: status,
  latency_ms: latency,
  error_code: response && response.error ? response.error.code : null,
  idempotency: gw.idempotency || null,
  idempotency_replay: !!x.replay,
  response_body: response,
  result_user_id: x.result_user_id || null,
  // agent steps of the request (spec 8.3), written to ai.agent_steps with the execution
  steps: Array.isArray(x.steps) ? x.steps : [],
  // reason and detail go to ai.executions.error only, never to the client
  error_detail: x.log ? [x.log.reason, x.log.detail].filter(Boolean).join(': ').slice(0, 500) : null,
};
const headers = { 'X-Request-Id': requestId || '', 'Cache-Control': 'no-store' };
if (status === 429) {
  const d = (response.error && response.error.details || []).find((y) => y.retry_after_s);
  if (d) headers['Retry-After'] = String(d.retry_after_s);
}
return [{ json: { status, response, finish, headers } }];
